// Python-compatibility helpers: code-point aware string utilities and
// CPython-compatible number formatting (repr of float, str of int).

// Convert a JS string to an array of single-code-point strings so that
// indexing/length semantics match Python's str.
export function cps(str) {
  return Array.from(str);
}

export function cpOf(ch) {
  return ch.codePointAt(0);
}

export function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

export function isHexDigit(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

export function isAlphaNum(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
}

// CPython repr() of a double (shortest round-trip representation).
// Only finite numbers are handled here.
export function pythonFloatRepr(x) {
  let sign = '';
  let a = x;
  if (a < 0 || (a === 0 && 1 / a < 0)) {
    sign = '-';
    a = -a;
  }
  if (a === 0) return sign + '0.0';
  // Find the shortest precision that round-trips.
  let digits = null;
  let exp10 = 0;
  for (let p = 1; p <= 17; p++) {
    const t = a.toExponential(p - 1);
    if (Number(t) === a) {
      const eIdx = t.indexOf('e');
      const mant = t.slice(0, eIdx);
      exp10 = parseInt(t.slice(eIdx + 1), 10);
      digits = mant.replace('.', '');
      // strip trailing zeros that toExponential may keep (it shouldn't for
      // the shortest p, but be safe)
      while (digits.length > 1 && digits.endsWith('0')) digits = digits.slice(0, -1);
      break;
    }
  }
  if (digits === null) {
    const t = a.toExponential(16);
    const eIdx = t.indexOf('e');
    exp10 = parseInt(t.slice(eIdx + 1), 10);
    digits = t.slice(0, eIdx).replace('.', '');
    while (digits.length > 1 && digits.endsWith('0')) digits = digits.slice(0, -1);
  }
  const len = digits.length;
  let out;
  if (exp10 >= -4 && exp10 <= 15) {
    // fixed notation
    if (exp10 >= len - 1) {
      out = digits + '0'.repeat(exp10 - len + 1) + '.0';
    } else if (exp10 >= 0) {
      out = digits.slice(0, exp10 + 1) + '.' + digits.slice(exp10 + 1);
    } else {
      out = '0.' + '0'.repeat(-exp10 - 1) + digits;
    }
  } else {
    // exponential notation: d[.ddd]e±XX (at least two exponent digits)
    let mant = digits[0];
    if (len > 1) mant += '.' + digits.slice(1);
    const es = exp10 < 0 ? '-' : '+';
    let ea = String(Math.abs(exp10));
    if (ea.length < 2) ea = '0' + ea;
    out = mant + 'e' + es + ea;
  }
  return sign + out;
}

// PyYAML SafeRepresenter.represent_float behaviour.
export function representFloat(x) {
  if (Number.isNaN(x)) return '.nan';
  if (x === Infinity) return '.inf';
  if (x === -Infinity) return '-.inf';
  let value = pythonFloatRepr(x);
  if (!value.includes('.') && !value.includes('e')) {
    value += '.0';
  } else if (value.includes('e') && !value.includes('.')) {
    value = value.replace('e', '.0e');
  }
  return value;
}

// str(int) for our integer values (Number in safe range or BigInt).
export function representInt(v) {
  if (typeof v === 'bigint') return v.toString();
  return String(v);
}

