// Token scanner — a faithful behavioural port of PyYAML's scanner.
// Produces the token stream consumed by the parser.

import { Reader, YamlError } from './reader.mjs';
import * as T from './tokens.mjs';

export class ScannerError extends YamlError {
  constructor(context, contextMark, problem, problemMark) {
    let msg = '';
    if (context) msg += context + '\n';
    if (contextMark) msg += '  in "<unicode string>", ' + contextMark + '\n';
    msg += problem;
    if (problemMark) msg += '\n  in "<unicode string>", ' + problemMark;
    super(msg);
    this.name = 'yaml.scanner.ScannerError';
  }
}

const BLANK = '\0 \t\r\n  ';
const LINEBREAKS = '\r\n  ';
const FULL_LINEBREAKS = '\r\n    ';

const ESCAPE_REPLACEMENTS = {
  '0': '\0', 'a': '', 'b': ' ', 't': '\t', '\t': '\t',
  'n': '\n', 'v': '', 'f': ' ', 'r': '\r', 'e': '',
  ' ': ' ', '"': '"', '/': '/', '\\': '\\',
  'N': '', '_': ' ', 'L': ' ', 'P': ' ',
};
const ESCAPE_CODES = { 'x': 2, 'u': 4, 'U': 8 };

class SimpleKey {
  constructor(tokenNumber, required, index, line, column, mark) {
    this.tokenNumber = tokenNumber;
    this.required = required;
    this.index = index;
    this.line = line;
    this.column = column;
    this.mark = mark;
  }
}

export class Scanner {
  constructor(src) {
    this.r = new Reader(src);
    this.done = false;
    this.flowLevel = 0;
    this.tokens = [];
    this.tokensTaken = 0;
    this.indent = -1;
    this.indents = [];
    this.allowSimpleKey = true;
    this.possibleSimpleKeys = new Map();
  }

  // ---- token queue API ----

  checkToken(...kinds) {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length > 0) {
      if (kinds.length === 0) return true;
      return kinds.includes(this.tokens[0].kind);
    }
    return false;
  }

  peekToken() {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length > 0) return this.tokens[0];
    return null;
  }

  getToken() {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length > 0) {
      this.tokensTaken++;
      return this.tokens.shift();
    }
    return null;
  }

  needMoreTokens() {
    if (this.done) return false;
    if (this.tokens.length === 0) return true;
    const key = this.nextPossibleSimpleKey();
    if (key !== null && key === this.tokensTaken) return true;
    return false;
  }

  nextPossibleSimpleKey() {
    let min = null;
    for (const key of this.possibleSimpleKeys.values()) {
      if (min === null || key.tokenNumber < min) min = key.tokenNumber;
    }
    return min;
  }

  stalePossibleSimpleKeys() {
    for (const [level, key] of Array.from(this.possibleSimpleKeys.entries())) {
      if (key.line !== this.r.line || this.tokensTaken - key.tokenNumber > 1024) {
        if (key.required) {
          throw new ScannerError('while scanning a simple key', key.mark,
            "could not find expected ':'", this.r.getMark());
        }
        this.possibleSimpleKeys.delete(level);
      }
    }
  }

  savePossibleSimpleKey() {
    if (this.allowSimpleKey) {
      this.removePossibleSimpleKey();
      this.possibleSimpleKeys.set(this.flowLevel, new SimpleKey(
        this.tokensTaken + this.tokens.length, false,
        this.r.index, this.r.line, this.r.column, this.r.getMark()));
    }
  }

  removePossibleSimpleKey() {
    const key = this.possibleSimpleKeys.get(this.flowLevel);
    if (key !== undefined) {
      if (key.required) {
        throw new ScannerError('while scanning a simple key', key.mark,
          "could not find expected ':'", this.r.getMark());
      }
      this.possibleSimpleKeys.delete(this.flowLevel);
    }
  }

  // ---- indentation ----

  unwindIndent(col) {
    if (this.flowLevel) return;
    while (this.indent > col) {
      const mark = this.r.getMark();
      this.indent = this.indents.pop();
      this.tokens.push(T.simpleToken('block-end', mark, mark));
    }
  }

  addIndent(column) {
    if (column <= this.indent) return false;
    this.indents.push(this.indent);
    this.indent = column;
    return true;
  }

  // ---- main fetch ----

  fetchMoreTokens() {
    this.scanToNextToken();
    this.stalePossibleSimpleKeys();
    this.unwindIndent(this.r.column);
    const ch = this.r.peek();
    if (ch === '\0') return this.fetchStreamEnd();
    if (ch === '%' && this.checkDirective()) return this.fetchDirective();
    if (ch === '-' && this.checkDocumentStart()) return this.fetchDocumentIndicator('document-start');
    if (ch === '.' && this.checkDocumentEnd()) return this.fetchDocumentIndicator('document-end');
    if (ch === '[') return this.fetchFlowCollectionStart('flow-sequence-start');
    if (ch === '{') return this.fetchFlowCollectionStart('flow-mapping-start');
    if (ch === ']') return this.fetchFlowCollectionEnd('flow-sequence-end');
    if (ch === '}') return this.fetchFlowCollectionEnd('flow-mapping-end');
    if (ch === ',') return this.fetchFlowEntry();
    if (ch === '-' && this.checkBlockEntry()) return this.fetchBlockEntry();
    if (ch === '?' && this.checkKey()) return this.fetchKey();
    if (ch === ':' && this.checkValue()) return this.fetchValue();
    if (ch === '*') return this.fetchAlias();
    if (ch === '&') return this.fetchAnchor();
    if (ch === '!') return this.fetchTag();
    if (ch === '|' && !this.flowLevel) return this.fetchBlockScalar('|');
    if (ch === '>' && !this.flowLevel) return this.fetchBlockScalar('>');
    if (ch === "'") return this.fetchFlowScalar("'");
    if (ch === '"') return this.fetchFlowScalar('"');
    if (this.checkPlain()) return this.fetchPlain();
    throw new ScannerError('while scanning for the next token', null,
      `found character '${ch}' that cannot start any token`, this.r.getMark());
  }

  scanToNextToken() {
    let found = false;
    while (!found) {
      while (this.r.peek() === ' ') this.r.forward();
      if (this.r.peek() === '#') {
        while (!BLANK.includes(this.r.peek())) this.r.forward();
      }
      if (this.scanLineBreak()) {
        if (!this.flowLevel) this.allowSimpleKey = true;
      } else {
        found = true;
      }
    }
  }

  scanLineBreak() {
    const ch = this.r.peek();
    if ('\r\n'.includes(ch)) {
      this.r.forward();
      return '\n';
    } else if (ch === ' ' || ch === ' ') {
      this.r.forward();
      return ch;
    }
    return '';
  }

  // ---- stream end ----

  fetchStreamEnd() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.possibleSimpleKeys = new Map();
    const mark = this.r.getMark();
    this.tokens.push(T.streamEnd(mark));
    this.done = true;
  }

  // ---- directives ----

  checkDirective() {
    return this.r.column === 0;
  }

  fetchDirective() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanDirective());
  }

  scanDirective() {
    const startMark = this.r.getMark();
    this.r.forward();
    const name = this.scanDirectiveName(startMark);
    let value = null;
    if (name === 'YAML') {
      value = this.scanYamlDirectiveValue(startMark);
    } else if (name === 'TAG') {
      value = this.scanTagDirectiveValue(startMark);
    } else {
      while (!LINEBREAKS.includes(this.r.peek()) && this.r.peek() !== '\0') this.r.forward();
    }
    this.scanDirectiveIgnoredLine(startMark);
    return T.directive(name, value, startMark, this.r.getMark());
  }

  scanDirectiveName(startMark) {
    let length = 0;
    let ch = this.r.peek(length);
    while (isAlphaNum(ch) || ch === '-' || ch === '_') {
      length++;
      ch = this.r.peek(length);
    }
    if (length === 0) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected alphabetic or numeric character, but found '${this.r.peek()}'`, this.r.getMark());
    }
    const value = this.r.prefix(length);
    this.r.forward(length);
    ch = this.r.peek();
    if (!BLANK.includes(ch)) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected alphabetic or numeric character, but found '${ch}'`, this.r.getMark());
    }
    return value;
  }

  scanYamlDirectiveValue(startMark) {
    while (this.r.peek() === ' ') this.r.forward();
    const major = this.scanDirectiveNumber(startMark);
    if (this.r.peek() !== '.') {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a digit or '.', but found '${this.r.peek()}'`, this.r.getMark());
    }
    this.r.forward();
    const minor = this.scanDirectiveNumber(startMark);
    if (!BLANK.includes(this.r.peek())) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a digit or ' ', but found '${this.r.peek()}'`, this.r.getMark());
    }
    return [major, minor];
  }

  scanDirectiveNumber(startMark) {
    let length = 0;
    let ch = this.r.peek(length);
    while ('0' <= ch && ch <= '9') {
      length++;
      ch = this.r.peek(length);
    }
    if (length === 0) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a digit, but found '${this.r.peek()}'`, this.r.getMark());
    }
    const value = parseInt(this.r.prefix(length), 10);
    this.r.forward(length);
    return value;
  }

  scanTagDirectiveValue(startMark) {
    while (this.r.peek() === ' ') this.r.forward();
    const handle = this.scanTagHandle('directive', startMark);
    while (this.r.peek() === ' ') this.r.forward();
    const prefix = this.scanTagUri('directive', startMark);
    return [handle, prefix];
  }

  scanDirectiveIgnoredLine(startMark) {
    while (this.r.peek() === ' ') this.r.forward();
    if (this.r.peek() === '#') {
      while (!LINEBREAKS.includes(this.r.peek()) && this.r.peek() !== '\0') this.r.forward();
    }
    const ch = this.r.peek();
    if (!BLANK.includes(ch)) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a comment or a line break, but found '${ch}'`, this.r.getMark());
    }
    this.scanLineBreak();
  }

  // ---- document indicators ----

  checkDocumentStart() {
    return this.r.column === 0 && this.r.prefix(3) === '---' && BLANK.includes(this.r.peek(3));
  }

  checkDocumentEnd() {
    return this.r.column === 0 && this.r.prefix(3) === '...' && BLANK.includes(this.r.peek(3));
  }

  fetchDocumentIndicator(kind) {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    const startMark = this.r.getMark();
    this.r.forward(3);
    this.tokens.push(T.simpleToken(kind, startMark, this.r.getMark()));
  }

  // ---- flow ----

  fetchFlowCollectionStart(kind) {
    this.savePossibleSimpleKey();
    this.flowLevel++;
    this.allowSimpleKey = true;
    const startMark = this.r.getMark();
    this.r.forward();
    this.tokens.push(T.simpleToken(kind, startMark, this.r.getMark()));
  }

  fetchFlowCollectionEnd(kind) {
    this.removePossibleSimpleKey();
    this.flowLevel--;
    this.allowSimpleKey = false;
    const startMark = this.r.getMark();
    this.r.forward();
    this.tokens.push(T.simpleToken(kind, startMark, this.r.getMark()));
  }

  fetchFlowEntry() {
    this.removePossibleSimpleKey();
    this.allowSimpleKey = true;
    const startMark = this.r.getMark();
    this.r.forward();
    this.tokens.push(T.simpleToken('flow-entry', startMark, this.r.getMark()));
  }

  // ---- block entry / key / value ----

  checkBlockEntry() {
    return BLANK.includes(this.r.peek(1));
  }

  fetchBlockEntry() {
    if (!this.flowLevel) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(null, null, 'sequence entries are not allowed here', this.r.getMark());
      }
      if (this.addIndent(this.r.column)) {
        const mark = this.r.getMark();
        this.tokens.push(T.simpleToken('block-sequence-start', mark, mark));
      }
    }
    this.removePossibleSimpleKey();
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    const startMark = this.r.getMark();
    this.r.forward();
    this.tokens.push(T.simpleToken('block-entry', startMark, this.r.getMark()));
  }

  checkKey() {
    if (this.flowLevel) return true;
    return BLANK.includes(this.r.peek(1));
  }

  fetchKey() {
    const startMark = this.r.getMark();
    if (!this.flowLevel) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(null, null, 'mapping keys are not allowed here', this.r.getMark());
      }
      if (this.addIndent(this.r.column)) {
        const mark = this.r.getMark();
        this.tokens.push(T.simpleToken('block-mapping-start', mark, mark));
      }
    }
    this.removePossibleSimpleKey();
    this.savePossibleSimpleKey();
    this.allowSimpleKey = !this.flowLevel ? false : true;
    this.r.forward();
    this.tokens.push(T.simpleToken('key', startMark, this.r.getMark()));
  }

  checkValue() {
    if (this.flowLevel) return true;
    return BLANK.includes(this.r.peek(1));
  }

  fetchValue() {
    const key = this.possibleSimpleKeys.get(this.flowLevel);
    if (key !== undefined) {
      this.possibleSimpleKeys.delete(this.flowLevel);
      this.tokens.splice(key.tokenNumber - this.tokensTaken, 0,
        T.simpleToken('key', key.mark, key.mark));
      if (!this.flowLevel) {
        if (this.addIndent(key.column)) {
          this.tokens.splice(key.tokenNumber - this.tokensTaken, 0,
            T.simpleToken('block-mapping-start', key.mark, key.mark));
        }
      }
      this.allowSimpleKey = false;
    } else {
      if (!this.flowLevel) {
        if (!this.allowSimpleKey) {
          throw new ScannerError(null, null, 'mapping values are not allowed here', this.r.getMark());
        }
        if (this.addIndent(this.r.column)) {
          const mark = this.r.getMark();
          this.tokens.push(T.simpleToken('block-mapping-start', mark, mark));
        }
      }
      this.allowSimpleKey = !this.flowLevel ? false : true;
    }
    const startMark = this.r.getMark();
    this.r.forward();
    this.tokens.push(T.simpleToken('value', startMark, this.r.getMark()));
  }

  // ---- alias / anchor / tag ----

  fetchAlias() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor('alias'));
  }

  fetchAnchor() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor('anchor'));
  }

  scanAnchor(type) {
    const startMark = this.r.getMark();
    this.r.forward();
    let length = 0;
    let ch = this.r.peek(length);
    while (isAlphaNum(ch) || ch === '-' || ch === '_') {
      length++;
      ch = this.r.peek(length);
    }
    if (length === 0) {
      throw new ScannerError(`while scanning an ${type}`, startMark,
        `expected alphabetic or numeric character, but found '${this.r.peek()}'`, this.r.getMark());
    }
    const value = this.r.prefix(length);
    this.r.forward(length);
    ch = this.r.peek();
    if (!BLANK.includes(ch) && !'?:,[]{}%@`'.includes(ch)) {
      throw new ScannerError(`while scanning an ${type}`, startMark,
        `expected alphabetic or numeric character, but found '${ch}'`, this.r.getMark());
    }
    const endMark = this.r.getMark();
    return type === 'alias' ? T.aliasToken(value, startMark, endMark)
      : T.anchorToken(value, startMark, endMark);
  }

  fetchTag() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanTag());
  }

  scanTag() {
    const startMark = this.r.getMark();
    let ch = this.r.peek(1);
    let handle, suffix;
    if (ch === '<') {
      handle = null;
      this.r.forward(2);
      suffix = this.scanTagUri('tag', startMark);
      if (this.r.peek() !== '>') {
        throw new ScannerError('while parsing a tag', startMark,
          `expected '>', but found '${this.r.peek()}'`, this.r.getMark());
      }
      this.r.forward();
    } else if (BLANK.includes(ch)) {
      handle = null;
      suffix = '!';
      this.r.forward();
    } else {
      let length = 1;
      let useHandle = false;
      while (!BLANK.includes(ch)) {
        if (ch === '!') { useHandle = true; break; }
        length++;
        ch = this.r.peek(length);
      }
      if (useHandle) {
        handle = this.scanTagHandle('tag', startMark);
      } else {
        handle = '!';
        this.r.forward();
      }
      suffix = this.scanTagUri('tag', startMark);
    }
    ch = this.r.peek();
    if (!BLANK.includes(ch)) {
      throw new ScannerError('while scanning a tag', startMark,
        `expected ' ', but found '${ch}'`, this.r.getMark());
    }
    return T.tagToken(handle, suffix, startMark, this.r.getMark());
  }

  scanTagHandle(name, startMark) {
    let ch = this.r.peek();
    if (ch !== '!') {
      throw new ScannerError(`while scanning a ${name}`, startMark,
        `expected '!', but found '${ch}'`, this.r.getMark());
    }
    let length = 1;
    ch = this.r.peek(length);
    while (isAlphaNum(ch) || ch === '-' || ch === '_') {
      length++;
      ch = this.r.peek(length);
    }
    if (ch !== '!') {
      this.r.forward(length);
      throw new ScannerError(`while scanning a ${name}`, startMark,
        `expected '!', but found '${ch}'`, this.r.getMark());
    }
    length++;
    const value = this.r.prefix(length);
    this.r.forward(length);
    return value;
  }

  scanTagUri(name, startMark) {
    let chunks = [];
    let length = 0;
    let ch = this.r.peek(length);
    while (isAlphaNum(ch) || "-;/?:@&=+$,_.!~*'()[]%".includes(ch)) {
      if (ch === '%') {
        chunks.push(this.r.prefix(length));
        this.r.forward(length);
        length = 0;
        chunks.push(this.scanUriEscapes(name, startMark));
      } else {
        length++;
      }
      ch = this.r.peek(length);
    }
    if (length) {
      chunks.push(this.r.prefix(length));
      this.r.forward(length);
    }
    if (chunks.length === 0) {
      throw new ScannerError(`while scanning a ${name}`, startMark,
        `expected URI, but found '${ch}'`, this.r.getMark());
    }
    return chunks.join('');
  }

  scanUriEscapes(name, startMark) {
    const bytes = [];
    let mark = this.r.getMark();
    while (this.r.peek() === '%') {
      this.r.forward();
      let k;
      for (k = 0; k < 2; k++) {
        if (!isHex(this.r.peek(k))) {
          throw new ScannerError(`while scanning a ${name}`, startMark,
            `expected URI escape sequence of 2 hexadecimal numbers, but found '${this.r.peek(k)}'`,
            this.r.getMark());
        }
      }
      bytes.push(parseInt(this.r.prefix(2), 16));
      this.r.forward(2);
    }
    // decode UTF-8 bytes
    return utf8Decode(bytes);
  }

  // ---- scalars ----

  fetchBlockScalar(style) {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanBlockScalar(style));
  }

  fetchFlowScalar(style) {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanFlowScalar(style));
  }

  fetchPlain() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanPlain());
  }

  checkPlain() {
    const ch = this.r.peek();
    return !BLANK.includes(ch) && !'-?:,[]{}#&*!|>\'"%@`'.includes(ch) ||
      (ch === '-' && !BLANK.includes(this.r.peek(1))) ||
      (!this.flowLevel && (ch === '?' || ch === ':') && !BLANK.includes(this.r.peek(1))) ||
      (this.flowLevel && (ch === '?' || ch === ':') && !BLANK.includes(this.r.peek(1)) && !',[]{}'.includes(this.r.peek(1)));
  }

  scanPlain() {
    const chunks = [];
    const startMark = this.r.getMark();
    let endMark = startMark;
    const indent = this.indent + 1;
    let spaces = [];
    while (true) {
      let length = 0;
      if (this.r.peek() === '#') break;
      while (true) {
        const ch = this.r.peek(length);
        const next = this.r.peek(length + 1);
        if (BLANK.includes(ch) ||
          (!this.flowLevel && ch === ':' && BLANK.includes(next)) ||
          (this.flowLevel && (ch === ',' || ch === '[' || ch === ']' || ch === '{' || ch === '}')) ||
          (this.flowLevel && ch === ':' && (BLANK.includes(next) || ',[]{}'.includes(next)))) {
          break;
        }
        length++;
      }
      if (length === 0) break;
      this.allowSimpleKey = false;
      chunks.push(...spaces);
      chunks.push(this.r.prefix(length));
      this.r.forward(length);
      endMark = this.r.getMark();
      spaces = this.scanPlainSpaces(indent, startMark);
      if (spaces === null || spaces.length === 0 || this.r.peek() === '#' ||
        (!this.flowLevel && this.r.column < indent)) {
        break;
      }
    }
    return T.scalarToken(chunks.join(''), true, startMark, endMark);
  }

  scanPlainSpaces(indent, startMark) {
    const chunks = [];
    let length = 0;
    while (this.r.peek(length) === ' ') length++;
    const whitespaces = this.r.prefix(length);
    this.r.forward(length);
    const ch = this.r.peek();
    if (LINEBREAKS.includes(ch)) {
      const lineBreak = this.scanLineBreak();
      this.allowSimpleKey = true;
      let prefix = this.r.prefix(3);
      if ((prefix === '---' || prefix === '...') && BLANK.includes(this.r.peek(3))) {
        return null;
      }
      const breaks = [];
      while (this.r.peek() === ' ' || LINEBREAKS.includes(this.r.peek())) {
        if (this.r.peek() === ' ') {
          this.r.forward();
        } else {
          breaks.push(this.scanLineBreak());
          prefix = this.r.prefix(3);
          if ((prefix === '---' || prefix === '...') && BLANK.includes(this.r.peek(3))) {
            return null;
          }
        }
      }
      if (lineBreak !== '\n') {
        chunks.push(lineBreak);
      } else if (breaks.length === 0) {
        chunks.push(' ');
      }
      chunks.push(...breaks);
    } else if (whitespaces) {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanFlowScalar(style) {
    const double = style === '"';
    const chunks = [];
    const startMark = this.r.getMark();
    const quote = this.r.peek();
    this.r.forward();
    chunks.push(...this.scanFlowScalarNonSpaces(double, startMark));
    while (this.r.peek() !== quote) {
      chunks.push(...this.scanFlowScalarSpaces(double, startMark));
      chunks.push(...this.scanFlowScalarNonSpaces(double, startMark));
    }
    this.r.forward();
    return T.scalarToken(chunks.join(''), false, startMark, this.r.getMark(), style);
  }

  scanFlowScalarNonSpaces(double, startMark) {
    const chunks = [];
    while (true) {
      let length = 0;
      while (!BLANK.includes(this.r.peek(length)) && !"'\"\\".includes(this.r.peek(length))) {
        length++;
      }
      if (length) {
        chunks.push(this.r.prefix(length));
        this.r.forward(length);
      }
      const ch = this.r.peek();
      if (!double && ch === "'" && this.r.peek(1) === "'") {
        chunks.push("'");
        this.r.forward(2);
      } else if ((double && ch === "'") || (!double && (ch === '"' || ch === '\\'))) {
        chunks.push(ch);
        this.r.forward();
      } else if (double && ch === '\\') {
        this.r.forward();
        const ch2 = this.r.peek();
        if (ch2 in ESCAPE_REPLACEMENTS) {
          chunks.push(ESCAPE_REPLACEMENTS[ch2]);
          this.r.forward();
        } else if (ch2 in ESCAPE_CODES) {
          const len = ESCAPE_CODES[ch2];
          this.r.forward();
          for (let k = 0; k < len; k++) {
            if (!isHex(this.r.peek(k))) {
              throw new ScannerError('while scanning a double-quoted scalar', startMark,
                `expected escape sequence of ${len} hexadecimal numbers, but found '${this.r.peek(k)}'`,
                this.r.getMark());
            }
          }
          const code = parseInt(this.r.prefix(len), 16);
          chunks.push(String.fromCodePoint(code));
          this.r.forward(len);
        } else if (LINEBREAKS.includes(ch2)) {
          this.scanLineBreak();
          chunks.push(...this.scanFlowScalarBreaks(double, startMark));
        } else {
          throw new ScannerError('while scanning a double-quoted scalar', startMark,
            `found unknown escape character '${ch2}'`, this.r.getMark());
        }
      } else {
        return chunks;
      }
    }
  }

  scanFlowScalarSpaces(double, startMark) {
    const chunks = [];
    let length = 0;
    while (this.r.peek(length) === ' ' || this.r.peek(length) === '\t') length++;
    const whitespaces = this.r.prefix(length);
    this.r.forward(length);
    const ch = this.r.peek();
    if (ch === '\0') {
      throw new ScannerError('while scanning a quoted scalar', startMark,
        'found unexpected end of stream', this.r.getMark());
    } else if (LINEBREAKS.includes(ch)) {
      const lineBreak = this.scanLineBreak();
      const breaks = this.scanFlowScalarBreaks(double, startMark);
      if (lineBreak !== '\n') {
        chunks.push(lineBreak);
      } else if (breaks.length === 0) {
        chunks.push(' ');
      }
      chunks.push(...breaks);
    } else {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanFlowScalarBreaks(double, startMark) {
    const chunks = [];
    while (true) {
      const prefix = this.r.prefix(3);
      if ((prefix === '---' || prefix === '...') && BLANK.includes(this.r.peek(3))) {
        throw new ScannerError('while scanning a quoted scalar', startMark,
          'found unexpected document separator', this.r.getMark());
      }
      while (this.r.peek() === ' ' || this.r.peek() === '\t') this.r.forward();
      if (LINEBREAKS.includes(this.r.peek())) {
        chunks.push(this.scanLineBreak());
      } else {
        return chunks;
      }
    }
  }

  scanBlockScalar(style) {
    const folded = style === '>';
    const chunks = [];
    const startMark = this.r.getMark();
    this.r.forward();
    const [chomping, increment] = this.scanBlockScalarIndicators(startMark);
    this.scanBlockScalarIgnoredLine(startMark);

    let minIndent = this.indent + 1;
    if (minIndent < 1) minIndent = 1;
    let indent, breaks, endMark;
    if (increment === null) {
      [breaks, indent, endMark] = this.scanBlockScalarIndentation();
      indent = Math.max(minIndent, indent);
    } else {
      indent = minIndent + increment - 1;
      [breaks, endMark] = this.scanBlockScalarBreaks(indent);
    }

    let lineBreak = '';
    while (this.r.column === indent && this.r.peek() !== '\0') {
      chunks.push(...breaks);
      const leadingNonSpace = this.r.peek() !== ' ' && this.r.peek() !== '\t';
      let length = 0;
      while (!BLANK.includes(this.r.peek(length))) length++;
      chunks.push(this.r.prefix(length));
      this.r.forward(length);
      lineBreak = this.scanLineBreak();
      [breaks, endMark] = this.scanBlockScalarBreaks(indent);
      if (this.r.column === indent && this.r.peek() !== '\0') {
        if (folded && lineBreak === '\n' && leadingNonSpace &&
          this.r.peek() !== ' ' && this.r.peek() !== '\t') {
          if (breaks.length === 0) chunks.push(' ');
        } else {
          chunks.push(lineBreak);
        }
      } else {
        break;
      }
    }

    if (chomping !== false) {
      chunks.push(lineBreak);
    }
    if (chomping === true) {
      chunks.push(...breaks);
    }
    return T.scalarToken(chunks.join(''), false, startMark, endMark, style);
  }

  scanBlockScalarIndicators(startMark) {
    let chomping = null;
    let increment = null;
    let ch = this.r.peek();
    if (ch === '+' || ch === '-') {
      chomping = ch === '+';
      this.r.forward();
      ch = this.r.peek();
      if (ch >= '0' && ch <= '9') {
        increment = ch.charCodeAt(0) - 48;
        if (increment === 0) {
          throw new ScannerError('while scanning a block scalar', startMark,
            'expected indentation indicator in the range 1-9, but found 0', this.r.getMark());
        }
        this.r.forward();
      }
    } else if (ch >= '0' && ch <= '9') {
      increment = ch.charCodeAt(0) - 48;
      if (increment === 0) {
        throw new ScannerError('while scanning a block scalar', startMark,
          'expected indentation indicator in the range 1-9, but found 0', this.r.getMark());
      }
      this.r.forward();
      ch = this.r.peek();
      if (ch === '+' || ch === '-') {
        chomping = ch === '+';
        this.r.forward();
      }
    }
    ch = this.r.peek();
    if (!BLANK.includes(ch)) {
      throw new ScannerError('while scanning a block scalar', startMark,
        `expected chomping or indentation indicators, but found '${ch}'`, this.r.getMark());
    }
    return [chomping, increment];
  }

  scanBlockScalarIgnoredLine(startMark) {
    while (this.r.peek() === ' ') this.r.forward();
    if (this.r.peek() === '#') {
      while (!BLANK.includes(this.r.peek())) this.r.forward();
    }
    const ch = this.r.peek();
    if (!BLANK.includes(ch)) {
      throw new ScannerError('while scanning a block scalar', startMark,
        `expected a comment or a line break, but found '${ch}'`, this.r.getMark());
    }
    this.scanLineBreak();
  }

  scanBlockScalarIndentation() {
    const chunks = [];
    let maxIndent = 0;
    let endMark = this.r.getMark();
    while (this.r.peek() === ' ' || LINEBREAKS.includes(this.r.peek())) {
      if (this.r.peek() !== ' ') {
        chunks.push(this.scanLineBreak());
        endMark = this.r.getMark();
      } else {
        this.r.forward();
        if (this.r.column > maxIndent) maxIndent = this.r.column;
      }
    }
    return [chunks, maxIndent, endMark];
  }

  scanBlockScalarBreaks(indent) {
    const chunks = [];
    let endMark = this.r.getMark();
    while (this.r.column < indent && this.r.peek() === ' ') this.r.forward();
    while (LINEBREAKS.includes(this.r.peek())) {
      chunks.push(this.scanLineBreak());
      endMark = this.r.getMark();
      while (this.r.column < indent && this.r.peek() === ' ') this.r.forward();
    }
    return [chunks, endMark];
  }
}

function isAlphaNum(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
}

function isHex(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

function utf8Decode(bytes) {
  let out = '';
  let i = 0;
  while (i < bytes.length) {
    const b = bytes[i];
    let cp, n;
    if (b < 0x80) { cp = b; n = 1; }
    else if ((b & 0xe0) === 0xc0) { cp = b & 0x1f; n = 2; }
    else if ((b & 0xf0) === 0xe0) { cp = b & 0x0f; n = 3; }
    else if ((b & 0xf8) === 0xf0) { cp = b & 0x07; n = 4; }
    else { cp = b; n = 1; }
    for (let k = 1; k < n && i + k < bytes.length; k++) {
      cp = (cp << 6) | (bytes[i + k] & 0x3f);
    }
    out += String.fromCodePoint(cp);
    i += n;
  }
  return out;
}

