// Parser + composer: turns the token stream into a node tree.
// Behaviourally mirrors PyYAML's parser.py + composer.py, including
// implicit tag resolution at composition time and anchor handling.

import { Scanner, ScannerError } from './scanner.mjs';
import { YamlError } from './reader.mjs';
import { ScalarNode, SequenceNode, MappingNode } from './nodes.mjs';
import { resolveScalarTag, TAG_SEQ, TAG_MAP, TAG_PREFIX } from './resolver.mjs';

export class ParserError extends YamlError {
  constructor(context, contextMark, problem, problemMark) {
    let msg = '';
    if (context) msg += context + '\n';
    if (contextMark) msg += '  in "<unicode string>", ' + contextMark + '\n';
    msg += problem;
    if (problemMark) msg += '\n  in "<unicode string>", ' + problemMark;
    super(msg);
    this.name = 'yaml.parser.ParserError';
  }
}

export class ComposerError extends YamlError {
  constructor(context, contextMark, problem, problemMark) {
    let msg = '';
    if (context) msg += context + '\n';
    if (contextMark) msg += '  in "<unicode string>", ' + contextMark + '\n';
    msg += problem;
    if (problemMark) msg += '\n  in "<unicode string>", ' + problemMark;
    super(msg);
    this.name = 'yaml.composer.ComposerError';
  }
}

const DEFAULT_TAGS = { '!': '!', '!!': 'tag:yaml.org,2002:' };

export function parseStream(src) {
  const p = new Parser(src);
  return p.getSingleNode();
}

class Parser {
  constructor(src) {
    this.scanner = new Scanner(src);
    this.anchors = new Map();
    this.tagHandles = { ...DEFAULT_TAGS };
  }

  checkToken(...kinds) { return this.scanner.checkToken(...kinds); }
  peekToken() { return this.scanner.peekToken(); }
  getToken() { return this.scanner.getToken(); }

  getSingleNode() {
    // STREAM-START
    this.getToken();
    let node = null;
    if (!this.checkToken('stream-end')) {
      node = this.parseDocument();
    }
    if (!this.checkToken('stream-end')) {
      const token = this.peekToken();
      throw new ComposerError('expected a single document in the stream',
        node ? node.startMark : token.startMark,
        'but found another document', token.startMark);
    }
    this.getToken(); // STREAM-END
    return node;
  }

  parseDocument() {
    this.processDirectives();
    if (!this.checkToken('document-start')) {
      const token = this.peekToken();
      throw new ParserError(null, null,
        `expected '<document start>', but found '${token.kind}'`, token.startMark);
    }
    this.getToken(); // DOCUMENT-START
    this.anchors = new Map();
    let node;
    if (this.checkToken('directive', 'document-start', 'document-end', 'stream-end')) {
      const token = this.peekToken();
      node = new ScalarNode(null, '', null, true, token.startMark, token.endMark);
      node.tag = resolveScalarTag('', true);
    } else {
      node = this.parseNode();
    }
    if (this.checkToken('document-end')) {
      this.getToken();
    }
    return node;
  }

  processDirectives() {
    const handles = {};
    let yamlVersion = null;
    while (this.checkToken('directive')) {
      const token = this.getToken();
      if (token.name === 'YAML') {
        if (yamlVersion !== null) {
          throw new ParserError(null, null, 'found duplicate YAML directive', token.startMark);
        }
        yamlVersion = token.value;
        if (yamlVersion[0] !== 1) {
          throw new ParserError(null, null,
            'found incompatible YAML document (version 1.* is required)', token.startMark);
        }
      } else if (token.name === 'TAG') {
        const [handle, prefix] = token.value;
        if (handle in handles) {
          throw new ParserError(null, null,
            `duplicate tag handle '${handle}'`, token.startMark);
        }
        handles[handle] = prefix;
      }
    }
    this.tagHandles = { ...DEFAULT_TAGS, ...handles };
  }

  parseNode(block = false, indentlessSequence = false) {
    let anchor = null;
    let tag = null;
    let startMark = null;
    let token;

    if (this.checkToken('alias')) {
      token = this.getToken();
      if (!this.anchors.has(token.value)) {
        throw new ComposerError(null, null,
          `found undefined alias '${token.value}'`, token.startMark);
      }
      return this.anchors.get(token.value);
    }

    if (this.checkToken('anchor')) {
      token = this.getToken();
      startMark = token.startMark;
      anchor = token.value;
      if (this.checkToken('tag')) {
        token = this.getToken();
        tag = token;
      }
    } else if (this.checkToken('tag')) {
      token = this.getToken();
      startMark = token.startMark;
      tag = token;
      if (this.checkToken('anchor')) {
        token = this.getToken();
        anchor = token.value;
      }
    }

    let resolvedTag = null;
    if (tag !== null) {
      if (tag.handle !== null) {
        if (!(tag.handle in this.tagHandles)) {
          throw new ParserError('while parsing a node', startMark,
            `found undefined tag handle '${tag.handle}'`, tag.startMark);
        }
        resolvedTag = this.tagHandles[tag.handle] + tag.suffix;
      } else {
        resolvedTag = tag.suffix;
      }
    }

    const register = (node) => {
      if (anchor !== null) this.anchors.set(anchor, node);
      return node;
    };

    if (resolvedTag === null && startMark === null && this.checkToken('scalar')) {
      token = this.peekToken();
      if (token.plain) {
        const node = new ScalarNode(null, token.value, token.style, true,
          token.startMark, token.endMark);
        node.tag = resolveScalarTag(token.value, true);
        this.getToken();
        return node;
      }
    }

    if (this.checkToken('scalar')) {
      token = this.getToken();
      const node = new ScalarNode(null, token.value, token.style, token.plain,
        token.startMark, token.endMark);
      if (resolvedTag === null || resolvedTag === '!') {
        node.tag = resolveScalarTag(token.value, token.plain);
      } else {
        node.tag = resolvedTag;
      }
      return register(node);
    }

    if (block && indentlessSequence && this.checkToken('block-entry')) {
      // sequence without BLOCK-SEQUENCE-START
      token = this.peekToken();
      const items = [];
      const node = new SequenceNode(
        resolvedTag === null || resolvedTag === '!' ? TAG_SEQ : resolvedTag,
        items, false);
      node.startMark = token.startMark;
      while (this.checkToken('block-entry')) {
        this.getToken();
        if (this.checkToken('block-entry', 'block-end', 'key', 'value', 'document-end', 'stream-end')) {
          items.push(this.emptyScalar());
        } else {
          items.push(this.parseNode(true));
        }
      }
      return register(node);
    }

    if (this.checkToken('block-sequence-start')) {
      const startTok = this.getToken();
      const items = [];
      const node = new SequenceNode(
        resolvedTag === null || resolvedTag === '!' ? TAG_SEQ : resolvedTag,
        items, false);
      node.startMark = startTok.startMark;
      while (this.checkToken('block-entry')) {
        this.getToken();
        if (this.checkToken('block-entry', 'block-end')) {
          items.push(this.emptyScalar());
        } else {
          items.push(this.parseNode(true));
        }
      }
      if (!this.checkToken('block-end')) {
        const t = this.peekToken();
        throw new ParserError('while parsing a block collection', startTok.startMark,
          `expected <block end>, but found '${t.kind}'`, t.startMark);
      }
      this.getToken();
      return register(node);
    }

    if (this.checkToken('block-mapping-start')) {
      const startTok = this.getToken();
      const pairs = [];
      const node = new MappingNode(
        resolvedTag === null || resolvedTag === '!' ? TAG_MAP : resolvedTag,
        pairs, false);
      node.startMark = startTok.startMark;
      while (this.checkToken('key')) {
        this.getToken();
        let keyNode;
        if (this.checkToken('key', 'value', 'block-end')) {
          keyNode = this.emptyScalar();
        } else {
          keyNode = this.parseNode(true);
        }
        let valueNode;
        if (this.checkToken('value')) {
          this.getToken();
          if (this.checkToken('key', 'value', 'block-end')) {
            valueNode = this.emptyScalar();
          } else {
            valueNode = this.parseNode(true, true);
          }
        } else {
          valueNode = this.emptyScalar();
        }
        pairs.push([keyNode, valueNode]);
      }
      if (!this.checkToken('block-end')) {
        const t = this.peekToken();
        throw new ParserError('while parsing a block mapping', startTok.startMark,
          `expected <block end>, but found '${t.kind}'`, t.startMark);
      }
      this.getToken();
      return register(node);
    }

    if (this.checkToken('flow-sequence-start')) {
      const startTok = this.getToken();
      const items = [];
      const node = new SequenceNode(
        resolvedTag === null || resolvedTag === '!' ? TAG_SEQ : resolvedTag,
        items, true);
      node.startMark = startTok.startMark;
      this.parseFlowSequenceItems(items, startTok);
      return register(node);
    }

    if (this.checkToken('flow-mapping-start')) {
      const startTok = this.getToken();
      const pairs = [];
      const node = new MappingNode(
        resolvedTag === null || resolvedTag === '!' ? TAG_MAP : resolvedTag,
        pairs, true);
      node.startMark = startTok.startMark;
      this.parseFlowMappingPairs(pairs, startTok);
      return register(node);
    }

    if (resolvedTag !== null || anchor !== null) {
      // empty scalar with properties
      const t = this.peekToken();
      const node = new ScalarNode(null, '', null, true, t.startMark, t.endMark);
      if (resolvedTag === null || resolvedTag === '!') {
        node.tag = resolveScalarTag('', true);
      } else {
        node.tag = resolvedTag;
      }
      return register(node);
    }

    const t = this.peekToken();
    throw new ParserError('while parsing a node', startMark,
      `expected the node content, but found '${t.kind}'`, t.startMark);
  }

  parseFlowSequenceItems(items, startTok) {
    let first = true;
    while (true) {
      if (this.checkToken('flow-sequence-end')) {
        this.getToken();
        return;
      }
      if (!first) {
        if (this.checkToken('flow-entry')) {
          this.getToken();
          if (this.checkToken('flow-sequence-end')) {
            this.getToken();
            return;
          }
        } else {
          const t = this.peekToken();
          throw new ParserError('while parsing a flow sequence', startTok.startMark,
            `expected ',' or ']', but got '${t.kind}'`, t.startMark);
        }
      }
      first = false;
      if (this.checkToken('key')) {
        // single-pair mapping inside a flow sequence: [key: value]
        this.getToken();
        let keyNode;
        if (this.checkToken('value', 'flow-entry', 'flow-sequence-end')) {
          keyNode = this.emptyScalar();
        } else {
          keyNode = this.parseNode();
        }
        let valueNode;
        if (this.checkToken('value')) {
          this.getToken();
          if (this.checkToken('flow-entry', 'flow-sequence-end')) {
            valueNode = this.emptyScalar();
          } else {
            valueNode = this.parseNode();
          }
        } else {
          valueNode = this.emptyScalar();
        }
        const m = new MappingNode(TAG_MAP, [[keyNode, valueNode]], true);
        m.startMark = keyNode.startMark;
        items.push(m);
      } else {
        items.push(this.parseNode());
      }
    }
  }

  parseFlowMappingPairs(pairs, startTok) {
    let first = true;
    while (true) {
      if (this.checkToken('flow-mapping-end')) {
        this.getToken();
        return;
      }
      if (!first) {
        if (this.checkToken('flow-entry')) {
          this.getToken();
          if (this.checkToken('flow-mapping-end')) {
            this.getToken();
            return;
          }
        } else {
          const t = this.peekToken();
          throw new ParserError('while parsing a flow mapping', startTok.startMark,
            `expected ',' or '}', but got '${t.kind}'`, t.startMark);
        }
      }
      first = false;
      if (this.checkToken('key')) {
        this.getToken();
        let keyNode;
        if (this.checkToken('value', 'flow-entry', 'flow-mapping-end')) {
          keyNode = this.emptyScalar();
        } else {
          keyNode = this.parseNode();
        }
        let valueNode;
        if (this.checkToken('value')) {
          this.getToken();
          if (this.checkToken('flow-entry', 'flow-mapping-end')) {
            valueNode = this.emptyScalar();
          } else {
            valueNode = this.parseNode();
          }
        } else {
          valueNode = this.emptyScalar();
        }
        pairs.push([keyNode, valueNode]);
      } else {
        // key without an explicit '?' indicator and without a value
        const keyNode = this.parseNode();
        pairs.push([keyNode, this.emptyScalar()]);
      }
    }
  }

  emptyScalar() {
    const t = this.peekToken();
    const mark = t ? t.startMark : null;
    const node = new ScalarNode(null, '', null, true, mark, mark);
    node.tag = resolveScalarTag('', true);
    return node;
  }
}

