// Safe constructor: turns the composed node tree into JS values,
// mirroring yaml.SafeConstructor semantics.

import {
  ScalarNode, SequenceNode, MappingNode,
  YAMLFloat, YAMLDate, YAMLDateTime, YAMLBytes, YAMLMap, YAMLSet, YAMLTuple,
  ConstructorError,
} from './nodes.mjs';
import {
  TAG_STR, TAG_SEQ, TAG_MAP, TAG_NULL, TAG_BOOL, TAG_INT, TAG_FLOAT,
  TAG_TIMESTAMP, TAG_MERGE, TAG_VALUE, TAG_BINARY, TAG_SET, TAG_OMAP, TAG_PAIRS,
} from './resolver.mjs';

const BOOL_VALUES = {
  yes: true, no: false, true: true, false: false, on: true, off: false,
};

export function constructDocument(node) {
  if (node === null) return null;
  return constructObject(node);
}

function constructObject(node) {
  if (node.kind === 'scalar') return constructScalar(node);
  if (node.kind === 'sequence') return constructSequence(node);
  return constructMappingNode(node);
}

function undefinedTag(node) {
  throw new ConstructorError(null, null,
    `could not determine a constructor for the tag '${node.tag}'`, node.startMark);
}

function constructScalar(node) {
  const tag = node.tag;
  const value = node.value;
  switch (tag) {
    case TAG_STR:
      return value;
    case TAG_NULL:
      return null;
    case TAG_BOOL:
      return BOOL_VALUES[value.toLowerCase()];
    case TAG_INT:
      return constructInt(value);
    case TAG_FLOAT:
      return new YAMLFloat(constructFloat(value));
    case TAG_TIMESTAMP:
      return constructTimestamp(value, node);
    case TAG_BINARY:
      return constructBinary(value, node);
    default:
      undefinedTag(node);
  }
}

function stripUnderscores(s) {
  let out = '';
  for (const ch of s) if (ch !== '_') out += ch;
  return out;
}

function constructInt(raw) {
  let value = stripUnderscores(raw);
  let sign = 1n;
  if (value[0] === '-') sign = -1n;
  if (value[0] === '-' || value[0] === '+') value = value.slice(1);
  let result;
  if (value === '0') {
    result = 0n;
  } else if (value.startsWith('0b')) {
    result = BigInt('0b' + value.slice(2));
  } else if (value.startsWith('0x')) {
    result = BigInt('0x' + value.slice(2));
  } else if (value[0] === '0') {
    result = BigInt('0o' + value);
  } else if (value.includes(':')) {
    const digits = value.split(':').map(p => BigInt(p));
    let v = 0n;
    for (const d of digits) v = v * 60n + d;
    result = v;
  } else {
    result = BigInt(value);
  }
  result *= sign;
  if (result <= BigInt(Number.MAX_SAFE_INTEGER) && result >= BigInt(-Number.MAX_SAFE_INTEGER)) {
    return Number(result);
  }
  return result;
}

function constructFloat(raw) {
  let value = stripUnderscores(raw).toLowerCase();
  let sign = 1;
  if (value[0] === '-') sign = -1;
  if (value[0] === '-' || value[0] === '+') value = value.slice(1);
  if (value === '.inf') return sign * Infinity;
  if (value === '.nan') return NaN;
  if (value.includes(':')) {
    const digits = value.split(':').map(p => Number(p));
    let v = 0;
    for (const d of digits) v = v * 60 + d;
    return sign * v;
  }
  return sign * Number(value);
}

const MONTH_DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function isLeap(y) {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function validDate(y, m, d) {
  if (m < 1 || m > 12) return false;
  let md = MONTH_DAYS[m - 1];
  if (m === 2 && isLeap(y)) md = 29;
  return d >= 1 && d <= md;
}

function timestampError(node) {
  throw new ConstructorError(null, null,
    'Invalid date/time value', node.startMark);
}

function constructTimestamp(value, node) {
  // field extraction per PyYAML's timestamp_regexp
  let i = 0;
  const n = value.length;
  const take = (max) => {
    let s = '';
    while (i < n && value[i] >= '0' && value[i] <= '9' && s.length < max) { s += value[i]; i++; }
    return s;
  };
  const year = parseInt(take(4), 10);
  i++; // '-'
  const month = parseInt(take(2), 10);
  i++; // '-'
  const day = parseInt(take(2), 10);
  if (!validDate(year, month, day)) timestampError(node);
  if (i >= n) {
    return new YAMLDate(year, month, day);
  }
  // separator
  if (value[i] === 'T' || value[i] === 't') i++;
  else while (i < n && (value[i] === ' ' || value[i] === '\t')) i++;
  const hour = parseInt(take(2), 10);
  i++; // ':'
  const minute = parseInt(take(2), 10);
  i++; // ':'
  const second = parseInt(take(2), 10);
  if (hour > 23 || minute > 59 || second > 59) timestampError(node);
  let microsecond = 0;
  if (i < n && value[i] === '.') {
    i++;
    let frac = '';
    while (i < n && value[i] >= '0' && value[i] <= '9') { frac += value[i]; i++; }
    frac = frac.slice(0, 6);
    while (frac.length < 6) frac += '0';
    microsecond = parseInt(frac, 10);
  }
  let tzMinutes = null;
  while (i < n && (value[i] === ' ' || value[i] === '\t')) i++;
  if (i < n) {
    if (value[i] === 'Z') {
      tzMinutes = 0;
    } else {
      const sign = value[i] === '-' ? -1 : 1;
      i++;
      const tzHour = parseInt(take(2), 10);
      let tzMinute = 0;
      if (i < n && value[i] === ':') {
        i++;
        tzMinute = parseInt(take(2), 10);
      }
      tzMinutes = sign * (tzHour * 60 + tzMinute);
    }
  }
  return new YAMLDateTime(year, month, day, hour, minute, second, microsecond, tzMinutes);
}

function constructBinary(value, node) {
  let cleaned = '';
  for (const ch of value) {
    if (ch !== ' ' && ch !== '\t' && ch !== '\n' && ch !== '\r' &&
      ch !== '' && ch !== ' ' && ch !== ' ') {
      cleaned += ch;
    }
  }
  try {
    return new YAMLBytes(new Uint8Array(Buffer.from(cleaned, 'base64')));
  } catch (e) {
    throw new ConstructorError(null, null, 'invalid base64 data', node.startMark);
  }
}

function constructSequence(node) {
  const tag = node.tag;
  if (tag === TAG_SEQ) {
    return node.value.map(constructObject);
  }
  if (tag === TAG_OMAP || tag === TAG_PAIRS) {
    const out = [];
    for (const sub of node.value) {
      if (sub.kind !== 'mapping') {
        throw new ConstructorError('while constructing an ordered map', node.startMark,
          `expected a mapping, but found ${sub.kind}`, sub.startMark);
      }
      if (sub.value.length !== 1) {
        throw new ConstructorError('while constructing an ordered map', node.startMark,
          'expected a single mapping item, but found more', sub.startMark);
      }
      const [k, v] = sub.value[0];
      out.push(new YAMLTuple([constructObject(k), constructObject(v)]));
    }
    return out;
  }
  undefinedTag(node);
}

function flattenMapping(node) {
  const merge = [];
  const rest = [];
  for (const [keyNode, valueNode] of node.value) {
    if (keyNode.tag === TAG_MERGE) {
      if (valueNode.kind === 'mapping') {
        flattenMapping(valueNode);
        merge.push(...valueNode.value);
      } else if (valueNode.kind === 'sequence') {
        const submerge = [];
        for (const sub of valueNode.value) {
          if (sub.kind !== 'mapping') {
            throw new ConstructorError('while constructing a mapping', node.startMark,
              `expected a mapping for merging, but found ${sub.kind}`, sub.startMark);
          }
          flattenMapping(sub);
          submerge.push(sub.value);
        }
        submerge.reverse();
        for (const value of submerge) merge.push(...value);
      } else {
        throw new ConstructorError('while constructing a mapping', node.startMark,
          `expected a mapping or list of mappings for merging, but found ${valueNode.kind}`,
          valueNode.startMark);
      }
    } else {
      if (keyNode.tag === TAG_VALUE) {
        keyNode = new ScalarNode(TAG_STR, '=', keyNode.style, keyNode.plain,
          keyNode.startMark, keyNode.endMark);
      }
      rest.push([keyNode, valueNode]);
    }
  }
  node.value = [...merge, ...rest];
}

function constructMappingNode(node) {
  const tag = node.tag;
  if (tag !== TAG_MAP && tag !== TAG_SET) undefinedTag(node);
  flattenMapping(node);
  if (tag === TAG_SET) {
    const set = new YAMLSet();
    for (const [keyNode] of node.value) {
      let key;
      try {
        key = constructObject(keyNode);
      } catch (e) {
        if (e instanceof ConstructorError) throw e;
        throw e;
      }
      set.add(key);
    }
    return set;
  }
  const map = new YAMLMap();
  for (const [keyNode, valueNode] of node.value) {
    const key = constructObject(keyNode);
    const value = constructObject(valueNode);
    try {
      map.set(key, value);
    } catch (e) {
      if (e instanceof ConstructorError && e.message === 'found unhashable key') {
        throw new ConstructorError('while constructing a mapping', node.startMark,
          'found unhashable key', keyNode.startMark);
      }
      throw e;
    }
  }
  return map;
}

